import base64, csv, gc, hashlib, io, json, os, subprocess, sys, tarfile, time
from pathlib import Path
subprocess.run([sys.executable, '-m', 'pip', 'uninstall', '-y', 'torchao'], check=True)
import torch
if not torch.cuda.is_available(): raise RuntimeError('GPU is required to merge the trained checkpoint')
raw = base64.b64decode('')
if hashlib.sha256(raw).hexdigest() != 'f4ccb5108f89826b700fbf27a9a6b9ef7d09d6da3778e93720a8f79508bb171b': raise RuntimeError('source archive mismatch')
root = Path('/kaggle/temp/export-src'); root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()), mode='r:') as inner:
            inner.extractall(root, filter='data')
sys.path[:0] = [str(root/'packages/ekido_core'), str(root/'runtime')]
from ekido_core.recipes import recipe, passes, eval_set_hash
from ekido_runtime.export import merge_checkpoint, to_gguf, quantize_gguf, llama_cli_generate
from ekido_runtime.llm import generate_answers
inputs = list(Path('/kaggle/input').rglob('fault-summary.json'))
if len(inputs) != 1: raise RuntimeError('Expected exactly one mounted two-T4 fault run')
source = inputs[0].parent
spec = json.loads((source/'spec.json').read_text(encoding='utf-8'))
baseline = json.loads((source/'train/evidence.json').read_text(encoding='utf-8'))
checkpoint = source/'train/checkpoints/step-400'
if baseline['completed_step'] != 400 or baseline['eval']['examples'] != 100: raise RuntimeError('Unexpected trained baseline evidence')
with (root/'experiments/recipes/ticket-sorter-hinglish/test.csv').open(encoding='utf-8',newline='') as f:
    rows = list(csv.DictReader(f))
if eval_set_hash('ticket-sorter-hinglish', rows) != baseline['eval']['eval_set_hash']:
    raise RuntimeError('Export evaluation set differs from training evaluation')
tmp = Path('/kaggle/temp/export-model'); tmp.mkdir(parents=True, exist_ok=True)
out = Path('/kaggle/working/gguf-comparison'); out.mkdir(parents=True, exist_ok=True)
llama = Path('/kaggle/temp/llama.cpp')
subprocess.run(['git','init',str(llama)],check=True)
subprocess.run(['git','-C',str(llama),'fetch','--depth','1','https://github.com/ggml-org/llama.cpp.git','f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d'],check=True)
subprocess.run(['git','-C',str(llama),'checkout','--detach','FETCH_HEAD'],check=True)
assert subprocess.check_output(['git','-C',str(llama),'rev-parse','HEAD'],text=True).strip() == 'f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d'
subprocess.run(['cmake','-S',str(llama),'-B',str(llama/'build'),'-DGGML_CUDA=OFF',
                '-DLLAMA_CURL=OFF','-DLLAMA_BUILD_TESTS=OFF'],check=True)
subprocess.run(['cmake','--build',str(llama/'build'),'--target','llama-cli','llama-quantize','-j','2'],check=True)
print('MERGE checkpoint',checkpoint,flush=True)
merged = tmp/'merged'
merge_checkpoint(spec,checkpoint,merged,device='cuda')
gc.collect(); torch.cuda.empty_cache()
from transformers import AutoModelForCausalLM, AutoTokenizer
tokenizer = AutoTokenizer.from_pretrained(merged)
hf_model = AutoModelForCausalLM.from_pretrained(merged, torch_dtype=torch.float32).to('cuda')
r = recipe('ticket-sorter-hinglish')
hf_answers = generate_answers(hf_model,tokenizer,[r.prompt(row['text']) for row in rows],
                              max_new_tokens=r.max_answer_tokens,
                              max_prompt_tokens=spec['max_seq_length']-r.max_answer_tokens,device='cuda')
hf_results = [{'gold':row['label'],'answer':answer,'passed':bool(passes(r.recipe_id,answer,row['label']))}
              for row,answer in zip(rows,hf_answers)]
if len(hf_results)!=len(rows): raise RuntimeError('Merged HF evaluation incomplete')
hf_score=sum(x['passed'] for x in hf_results)/len(hf_results)
print('MERGED_HF_RESULT',hf_score,flush=True)
del hf_model, tokenizer
gc.collect(); torch.cuda.empty_cache()
f16 = to_gguf(merged,tmp/'model-f16.gguf',llama_cpp=llama)
summary = {'core_revision':'0a9db037170024a1f32748e0b5dcbe14a1a88a3a','worker_revision':'74bf4e753ab30f4ce3b88a577a16b425c6fac923','llama_cpp_revision':'f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d',
           'source_checkpoint_step':400,'reference_pass_rate':baseline['eval']['pass_rate'],
           'reference_eval_set_hash':baseline['eval']['eval_set_hash'],
           'merged_hf':{'pass_rate':hf_score,'examples':len(hf_results),'answers':hf_results},
           'absolute_accuracy_tolerance':0.05,'tolerance_note':'Predeclared experiment tolerance, not a published policy',
           'test_note':'Previously reused synthetic test; not an independent quality estimate','quantizations':{}}
for quant in ('F16','Q4_K_M','Q8_0'):
    path = f16 if quant == 'F16' else quantize_gguf(f16,out/('model-'+quant+'.gguf'),quant,llama_cpp=llama)
    hasher = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda:f.read(4*1024*1024),b''): hasher.update(chunk)
    answers=[]
    for i,row in enumerate(rows):
        answer=llama_cli_generate(llama,path,r.prompt(row['text']),n_predict=r.max_answer_tokens)
        answers.append({'gold':row['label'],'answer':answer,'passed':bool(passes(r.recipe_id,answer,row['label']))})
        if (i+1)%20==0: print(quant,'evaluated',i+1,flush=True)
    score=sum(row['passed'] for row in answers)/len(answers)
    delta=score-baseline['eval']['pass_rate']
    summary['quantizations'][quant]={'pass_rate':score,'examples':len(answers),'difference':delta,
        'within_tolerance':abs(delta)<=0.05,'gguf_sha256':hasher.hexdigest(),'gguf_bytes':path.stat().st_size,
        'answers':answers}
    (out/'summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False),encoding='utf-8')
    print('RESULT',quant,'score',score,'delta',delta,flush=True)
